pm.test("Login ADMIN - 200", function () {
    pm.response.to.have.status(200);
});

if (pm.response.code === 200) {
    const resposta = pm.response.json();
    const token = resposta.accessToken;

    pm.expect(token).to.be.a("string").and.not.empty;

    // Salva o token nas variáveis da Collection
    pm.collectionVariables.set("jwt_token", token);

    // Remove um possível valor antigo do Environment
    pm.environment.unset("jwt_token");

    console.log("Token ADMIN salvo com sucesso!");
    console.log(
        "Token disponível:",
        Boolean(pm.collectionVariables.get("jwt_token"))
    );
}

pm.test("T04: HTTP 201", function () {
    pm.response.to.have.status(201);
});
if (pm.response.code >= 200 && pm.response.code < 300) {
  const data = pm.response.json();
  pm.expect(data.id, "unidade_id retornado").to.be.a('string').and.not.empty;
  pm.environment.set('unidade_id', data.id);
}

const tokenEnvironment = pm.environment.get("jwt_token");
const tokenResolvido = pm.variables.get("jwt_token");

console.log("Environment selecionado:", pm.environment.name);
console.log("Token no Environment:", Boolean(tokenEnvironment));
console.log("Token utilizado pelo Postman:", Boolean(tokenResolvido));
console.log(
    "Os tokens são iguais:",
    tokenEnvironment === tokenResolvido
);
console.log(
    "Formato JWT válido:",
    typeof tokenResolvido === "string" &&
    tokenResolvido.split(".").length === 3
);

